import{_ as a,o as i,c as t,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"Physics-Aware Video Generation","description":"","frontmatter":{"title":"Physics-Aware Video Generation","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/physics-aware.md","filePath":"en/tutorials/physics-aware.md","lastUpdated":null}'),n={name:"en/tutorials/physics-aware.md"};function s(o,e,l,h,c,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="physics-aware-video-generation" tabindex="-1">Physics-Aware Video Generation <a class="header-anchor" href="#physics-aware-video-generation" aria-label="Permalink to &quot;Physics-Aware Video Generation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/physics-aware">物理感知视频生成</a><strong>Coverage</strong>: June 2025 – July 2026, tracing back to VideoPhy, PhyGenBench, Physics-IQ, PhysGen, Cosmos and WISA. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-physics-aware">275 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/physics-aware">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>The organising contradiction is stated in Chapter 1: <strong>visual realism is not physical realism</strong>. A model can produce a frame no human calls fake while the object in it accelerates upward, loses mass, or passes through a wall. Physical plausibility is therefore a separate axis from perceptual quality, and it needs its own priors, its own data and its own benchmarks.</p><p>The tutorial&#39;s main contribution is a map of <strong>six ways physics can enter a video generator</strong>: simulation in the loop; physical priors and representation alignment; reinforcement learning and preference optimisation; agentic / VLM physical planning; training-free guidance at inference time; and physics-native architectures — with world-model-native systems treated as a seventh, cross-cutting family. Every method discussed later is placed in that map, and Chapter 2 closes with a decision table for choosing among them.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What we are covering</li><li>0.2 Why this is one of the hottest current directions</li><li>0.3 Suggested reading paths</li><li>0.4 Scope</li></ul><h3 id="chapter-1-—-concepts-and-intuition" tabindex="-1">Chapter 1 — Concepts and intuition <a class="header-anchor" href="#chapter-1-—-concepts-and-intuition" aria-label="Permalink to &quot;Chapter 1 — Concepts and intuition&quot;">​</a></h3><ul><li>1.1 What &quot;physics-aware video generation&quot; means</li><li>1.2 The core contradiction: visual realism ≠ physical realism</li><li>1.3 A taxonomy of physical phenomena (the coordinate system for the whole tutorial)</li><li>1.4 How physics enters video generation: five injection paradigms</li><li>1.5 Relation to adjacent fields</li><li>1.6 A unified mental model</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><ul><li>2.1 The substrate: diffusion / flow-matching video generation</li><li>2.2 Paradigm 1: simulation in the loop</li><li>2.3 Paradigm 2: physical priors and representation alignment</li><li>2.4 Paradigm 3: reinforcement learning and preference optimisation</li><li>2.5 Paradigm 4: agentic / VLM physical planning</li><li>2.6 Paradigm 5: training-free guidance at inference time</li><li>2.7 Coupling physics with world models and embodiment: action conditioning and inverse dynamics</li><li>2.8 Paradigm 6: physics-native architectures</li><li>2.9 Summary: a decision table for choosing a paradigm</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.1 Panorama of tasks</li><li>3.2 Task A: implicit physical plausibility in text/image-to-video</li><li>3.3 Task B: explicit controllable generation from physical parameters or forces</li><li>3.4 Task C: counterfactual and interventional generation</li><li>3.5 Task D: robotic and embodied world models</li><li>3.6 Task E: autonomous-driving world models</li><li>3.7 Task F: 4D and interactive worlds and scenes</li><li>3.8 Task G: scientific, engineering and domain-specific simulation</li><li>3.9 Task H: video models as probes of physical understanding, and as visual foundation models</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><ul><li>4.1 Why physics data is so hard</li><li>4.2 Three paradigms for constructing it</li><li>4.3 Representative physics video datasets (2025–2026)</li><li>4.4 Key techniques in data construction</li><li>4.5 Where the physical ground truth comes from</li></ul><h3 id="chapter-5-—-methods-and-representative-systems" tabindex="-1">Chapter 5 — Methods and representative systems <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems&quot;">​</a></h3><ul><li>5.1 Overview of the method families</li><li>5.2 Family A: simulation-guided generation</li><li>5.3 Family B: priors and representation alignment</li><li>5.4 Family C: RL and preference optimisation</li><li>5.5 Family D: agentic / VLM planning</li><li>5.6 Family E: training-free inference-time guidance</li><li>5.7 Family G: world-model-native systems</li><li>5.8 Family F: physics-native architectures — the most hardcore branch</li><li>5.9 Practical advice on composing families</li></ul><h3 id="chapter-6-—-benchmarks-and-metrics" tabindex="-1">Chapter 6 — Benchmarks and metrics <a class="header-anchor" href="#chapter-6-—-benchmarks-and-metrics" aria-label="Permalink to &quot;Chapter 6 — Benchmarks and metrics&quot;">​</a></h3><p>The longest evaluation chapter in the collection, because scoring physics requires deciding what &quot;correct&quot; even means for a generated video.</p><ul><li>6.1 Why evaluating physics is so hard</li><li>6.2 Foundational benchmarks you must know</li><li>6.3 General-purpose physics benchmarks (2025.07–2026.07)</li><li>6.4 Evaluation methodology: how scores are produced</li><li>6.5 Category-specific and specialised benchmarks</li><li>6.6 World-model, embodied and driving benchmarks</li><li>6.7 Reasoning benchmarks (chain-of-frames / video as reasoning)</li><li>6.8 Benchmark quick-reference, organised by what is being tested</li><li>6.9 Evaluation traps and best practice</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 Unsolved core challenges</li><li>7.2 Definite trend calls (2025 → 2026)</li><li>7.3 Open problems worth betting on</li><li>7.4 Advice for different roles</li></ul><h3 id="chapter-8-—-paper-and-resource-list-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper and resource list (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-and-resource-list-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper and resource list (2025.06–2026.07)&quot;">​</a></h3><p>Eighteen thematic groups plus a timeline: foundational work; benchmarks and evaluation; the six method families; physics-native architectures; world-model-native systems and infrastructure; robotics and embodied applications; driving world models; 4D and interactive worlds; datasets; physical rendering, lighting, intrinsics and editing; audio-visual physics; reasoning, probes, theory, PDEs and detection; surveys and position papers; and a curated resource list.</p><h3 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h3><ul><li>Chinese–English terminology quick reference</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/world-models">World Models</a> — action-conditioned simulators that must obey physics to be useful</li><li><a href="/notes/en/tutorials/video-for-embodied-ai">Video Generation for Embodied AI</a> — where physical error turns into task failure</li><li><a href="/notes/en/tutorials/post-training-rl">Post-Training &amp; Reinforcement Learning</a> — the reward-based branch of physical alignment</li></ul>',30)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
